func accelerationDecodeExceptionList(raw json.RawMessage) (accelerationExceptionListOwnedList, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if len(raw) == 0 {
		return accelerationExceptionListOwnedList{}, diagnostics
	}
	if accelerationJSONNull(raw) {
		diagnostics.AddError("Malformed web content acceleration result", "The successful API result contained null exception_list instead of an array.")
		return accelerationExceptionListOwnedList{}, diagnostics
	}
	var rawItems []json.RawMessage
	if err := json.Unmarshal(raw, &rawItems); err != nil {
		diagnostics.AddError("Malformed web content acceleration result", "The successful API result contained a non-array exception_list value.")
		return accelerationExceptionListOwnedList{}, diagnostics
	}
	if len(rawItems) > accelerationExceptionListMaxItems {
		diagnostics.AddError("Malformed web content acceleration result", fmt.Sprintf("The successful API result contained more than %d exception_list items.", accelerationExceptionListMaxItems))
		return accelerationExceptionListOwnedList{}, diagnostics
	}

	items := make([]accelerationExceptionListWireItem, 0, len(rawItems))
	seen := make(map[int]struct{}, len(rawItems))
	knownKeys := map[string]struct{}{
		"host":        {},
		"host_status": {},
		"idx":         {},
		"url_pattern": {},
		"url_type":    {},
	}
	for position, rawItem := range rawItems {
		location := fmt.Sprintf("exception_list item %d", position+1)
		var object map[string]json.RawMessage
		if err := json.Unmarshal(rawItem, &object); err != nil || object == nil {
			diagnostics.AddError("Malformed web content acceleration result", location+" was not an object.")
			continue
		}
		unknown := make([]string, 0)
		for key := range object {
			if _, ok := knownKeys[key]; !ok {
				unknown = append(unknown, key)
			}
		}
		sort.Strings(unknown)
		if len(unknown) != 0 {
			diagnostics.AddError("Unknown web content acceleration item field", location+" contained unsupported keys: "+strings.Join(unknown, ", ")+".")
			continue
		}
		index, ok := accelerationDecodeIndex(object["idx"], location, "int", &diagnostics)
		if !ok {
			continue
		}
		if _, duplicate := seen[index]; duplicate {
			diagnostics.AddError("Malformed web content acceleration result", fmt.Sprintf("%s used duplicate idx %d.", location, index))
			continue
		}
		seen[index] = struct{}{}
		item := accelerationExceptionListWireItem{Index: index}
		accelerationRejectItemNullUnlessNullable(object, "host", false, location, &diagnostics)
		item.Host = accelerationDecodeOptionalString(object, "host", location, 255, &diagnostics)
		host_statusValue, ok := accelerationDecodeRequiredBool(object["host_status"], location+" host_status", &diagnostics)
		if !ok {
			continue
		}
		item.HostStatus = host_statusValue
		url_patternValue, ok := accelerationDecodeRequiredString(object["url_pattern"], location+" url_pattern", &diagnostics)
		if !ok {
			continue
		}
		accelerationValidateString(location, " url_pattern", url_patternValue, 0, 255, &diagnostics)
		item.URLPattern = url_patternValue
		url_typeValue, ok := accelerationDecodeRequiredString(object["url_type"], location+" url_type", &diagnostics)
		if !ok {
			continue
		}
		accelerationValidateString(location, " url_type", url_typeValue, 0, 0, &diagnostics)
		if !accelerationExceptionListURLTypeValid(url_typeValue) {
			diagnostics.AddError("Malformed web content acceleration result", location+" url_type was not one of regex, string.")
		}
		item.URLType = url_typeValue
		items = append(items, item)
	}
	if diagnostics.HasError() {
		return accelerationExceptionListOwnedList{}, diagnostics
	}
	sort.Slice(items, func(i, j int) bool { return items[i].Index < items[j].Index })
	return accelerationExceptionListOwnedList{Set: true, Items: items}, diagnostics
}

func accelerationExceptionListWrapperValue(owned accelerationExceptionListOwnedList, subItemOwnedMasks map[string][]bool) (types.Object, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if !owned.Set {
		return types.ObjectNull(accelerationExceptionListWrapperAttributeTypes), diagnostics
	}
	elements := make([]attr.Value, 0, len(owned.Items))
	for _, item := range owned.Items {
		objectValues := map[string]attr.Value{}
		hostValue := types.StringNull()
		if item.Host != nil {
			hostValue = types.StringValue(*item.Host)
		}
		objectValues["host"] = hostValue
		objectValues["host_status"] = types.BoolValue(item.HostStatus)
		objectValues["url_pattern"] = types.StringValue(item.URLPattern)
		objectValues["url_type"] = types.StringValue(item.URLType)
		object, objectDiagnostics := types.ObjectValue(accelerationExceptionListItemAttributeTypes, objectValues)
		diagnostics.Append(objectDiagnostics...)
		elements = append(elements, object)
	}
	list, listDiagnostics := types.ListValue(types.ObjectType{AttrTypes: accelerationExceptionListItemAttributeTypes}, elements)
	diagnostics.Append(listDiagnostics...)
	wrapper, wrapperDiagnostics := types.ObjectValue(accelerationExceptionListWrapperAttributeTypes, map[string]attr.Value{"item": list})
	diagnostics.Append(wrapperDiagnostics...)
	return wrapper, diagnostics
}
func accelerationDecodeIndex(raw json.RawMessage, location string, idxKind string, diagnostics *diag.Diagnostics) (int, bool) {
	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 || accelerationJSONNull(trimmed) {
		diagnostics.AddError("Malformed web content acceleration result", location+" did not contain a non-null integer idx.")
		return 0, false
	}
	if trimmed[0] != '-' && (trimmed[0] < '0' || trimmed[0] > '9') {
		diagnostics.AddError("Malformed web content acceleration result", location+" contained a non-integer idx.")
		return 0, false
	}
	var number json.Number
	if err := json.Unmarshal(trimmed, &number); err != nil {
		diagnostics.AddError("Malformed web content acceleration result", location+" contained a non-integer idx.")
		return 0, false
	}
	value64, err := number.Int64()
	if err != nil || value64 <= 0 || int64(int(value64)) != value64 {
		diagnostics.AddError("Malformed web content acceleration result", location+" contained an idx that was not a positive integer.")
		return 0, false
	}
	return int(value64), true
}
