func accelerationOwnership(ctx context.Context, template bool, ownership wafmodule.OwnershipContext) (accelerationOwnershipSet, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if template {
		return accelerationOwnershipSet{ExceptionList: false}, diagnostics
	}
	if ownership.Source == wafmodule.OwnershipImported {
		return accelerationOwnershipSet{ExceptionList: true}, diagnostics
	}
	configsValue, ownershipDiagnostics := wafmodule.OwnershipConfigs(ctx, ownership)
	diagnostics.Append(ownershipDiagnostics...)
	if diagnostics.HasError() || configsValue.IsNull() {
		return accelerationOwnershipSet{ExceptionList: false}, diagnostics
	}
	if configsValue.IsUnknown() {
		diagnostics.AddError("Unknown web content acceleration ownership", "The configs ownership state was unknown while flattening.")
		return accelerationOwnershipSet{ExceptionList: false}, diagnostics
	}
	var configs accelerationConfigsModel
	diagnostics.Append(configsValue.As(ctx, &configs, basetypes.ObjectAsOptions{})...)
	return accelerationOwnershipSet{ExceptionList: !configs.ExceptionList.IsNull()}, diagnostics
}
func accelerationValidateString(location, label, value string, minimum, maximum int, diagnostics *diag.Diagnostics) {
	if minimum > 0 && utf8.RuneCountInString(value) < minimum {
		diagnostics.AddError("Invalid web content acceleration item", fmt.Sprintf("%s%s must be at least %d UTF-8 characters.", location, label, minimum))
	}
	if maximum > 0 && utf8.RuneCountInString(value) > maximum {
		diagnostics.AddError("Invalid web content acceleration item", fmt.Sprintf("%s%s exceeds %d UTF-8 characters.", location, label, maximum))
	}
}

